// 底部标签栏：窄屏时第一级菜单固定在屏幕底部，适合第一级菜单不多（不超过 5 个）的用户端。
// 顶部导航布局用 narrowNav="bottom" 开启它，其他布局也可以直接放置。

import { useBottomNav } from "@go-tenon/shell"
import type { ReactNode } from "react"
import { badgeText, MenuIcon, NavLink } from "@/components/tenon/nav"
import { cn } from "@/lib/utils"

/**
 * 底部标签栏。固定在屏幕底部，使用它的布局要给内容留出底部的空间（pb-16）。
 * 带刘海的手机上，底部的安全区域由 env(safe-area-inset-bottom) 留出。
 */
export function BottomNav({ max = 5 }: { max?: number }): ReactNode {
  const items = useBottomNav(max)
  if (items.length === 0) return null
  return (
    <nav
      aria-label="主导航"
      className="fixed inset-x-0 bottom-0 z-20 flex border-t bg-background/95 pb-[env(safe-area-inset-bottom)] backdrop-blur"
    >
      {items.map((item) => {
        const badge = badgeText(item.badge)
        return (
          <NavLink
            key={item.id}
            to={item.path}
            aria-current={item.active ? "page" : undefined}
            className={cn(
              "relative flex h-16 flex-1 flex-col items-center justify-center gap-1 text-xs",
              item.active ? "font-medium text-primary" : "text-muted-foreground",
            )}
          >
            <MenuIcon item={item} className="size-5" />
            <span>{item.title}</span>
            {badge && (
              <span className="absolute top-2 left-1/2 ml-2 min-w-4 rounded-full bg-destructive px-1 text-center text-[10px] leading-4 text-white">
                {badge}
              </span>
            )}
          </NavLink>
        )
      })}
    </nav>
  )
}

// 布局共用的部件：应用内的链接、面包屑、图标。由 tenon 的 shadcn registry 提供，加入项目后可以随意修改。

import { type MenuItem, pageUnder, useNavigation } from "@go-tenon/shell"
import { useRouter } from "@tanstack/react-router"
import {
  AppWindow,
  Bell,
  ChartColumn,
  FileText,
  Folder,
  House,
  LayoutDashboard,
  type LucideIcon,
  MessageSquare,
  Settings,
  Shield,
  ShoppingCart,
  Store,
  User,
  Users,
} from "lucide-react"
import { Fragment, type MouseEvent, type ReactNode } from "react"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"

/**
 * 路由元数据中 icon 的名字到 lucide 图标的映射。名字与运营后台（@go-tenon/admin 的 defaultIcons）相同，
 * 同一份路由元数据在两套外观中都能显示图标。需要别的图标时加在这里。
 */
export const icons: Record<string, LucideIcon> = {
  appstore: AppWindow,
  "bar-chart": ChartColumn,
  bell: Bell,
  dashboard: LayoutDashboard,
  "file-text": FileText,
  folder: Folder,
  home: House,
  message: MessageSquare,
  safety: Shield,
  setting: Settings,
  shop: Store,
  "shopping-cart": ShoppingCart,
  team: Users,
  user: User,
}

/** 菜单项的图标；没有登记的名字不显示。 */
export function MenuIcon({ item, className }: { item: Pick<MenuItem, "icon">; className?: string }): ReactNode {
  const Icon = item.icon ? icons[item.icon] : undefined
  return Icon ? <Icon className={className} /> : null
}

/** 应用内的链接：保留浏览器的默认行为（新窗口打开等），普通点击由路由跳转。 */
export function NavLink({
  to,
  children,
  className,
  ...rest
}: { to: string; children: ReactNode; className?: string } & Omit<React.ComponentProps<"a">, "href">): ReactNode {
  const router = useRouter()
  const onClick = (e: MouseEvent<HTMLAnchorElement>) => {
    rest.onClick?.(e)
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return
    e.preventDefault()
    void router.navigate({ href: to })
  }
  return (
    <a {...rest} href={router.buildLocation({ href: to } as never).href} className={className} onClick={onClick}>
      {children}
    </a>
  )
}

/** 面包屑：最后一级是当前页面；分组跳到它下面第一个可以进入的页面。 */
export function Crumbs(): ReactNode {
  const { crumbs, menu } = useNavigation()
  if (crumbs.length === 0) return null
  return (
    <Breadcrumb>
      <BreadcrumbList>
        {crumbs.map((c, i) => {
          const last = i === crumbs.length - 1
          const target = last ? undefined : pageUnder(menu, c.path)
          return (
            <Fragment key={c.path}>
              <BreadcrumbItem>
                {last ? (
                  <BreadcrumbPage>{c.title}</BreadcrumbPage>
                ) : target ? (
                  <BreadcrumbLink asChild>
                    <NavLink to={target}>{c.title}</NavLink>
                  </BreadcrumbLink>
                ) : (
                  c.title
                )}
              </BreadcrumbItem>
              {!last && <BreadcrumbSeparator />}
            </Fragment>
          )
        })}
      </BreadcrumbList>
    </Breadcrumb>
  )
}

/** 菜单项的徽标文字：数字、文字，true 是小红点。 */
export function badgeText(badge: MenuItem["badge"]): string | undefined {
  if (badge === undefined || badge === false) return undefined
  return badge === true ? "•" : String(badge)
}
